//! Replays the Node oracle sets in `tests/fixtures/rust-core/tokenizer` (generated by
//! `benchmarks/rust-core-oracles/tokenizer.oracle.test.ts`): tokenizer selection, the counts built on `encode`,
//! `strongBan`, `encodeWithTokenizer`, `tokenizeGoogleCloud`, the artifact table, and the vocabulary of each
//! SentencePiece model. Models are registered from `public/`; a case whose tokenizer this build leaves out must decline
//! before any host request, and each set pins how many such cases a build without `huggingface` has.

mod common;

use common::{declines, declines_as, left_out, ready};
use risunest_ir::chat::PromptMessage;
use risunest_ir::provider::{HttpMethod, HttpRequestSpec, ResponseKind};
use risunest_ir::stage::{Effect, HostReply, HostRequest, StageError, Step, TextContext, TextOutput, TextProcessor, TokenCounter, TokenInput};
use risunest_ir::{json, Budget, Limits, Text, Value};
use risunest_tokenizer::counter::account::{accurate_text, character_texts, chat_texts, CharacterFields, TextTotals, DYNAMIC, PERSISTANT};
use risunest_tokenizer::counter::ban::{cache_key, CaseTables, StrongBan};
use risunest_tokenizer::counter::encode::Encoder;
use risunest_tokenizer::counter::google::{GoogleCloud, GoogleCloudMemo};
use risunest_tokenizer::counter::{ChatAccounting, Counter};
use risunest_tokenizer::id::sentencepiece::{self, ModelType, PieceType};
use risunest_tokenizer::id::{encode_with_tokenizer, select, ArtifactFormat, ModelTokenizer, PluginOptions, TokenizerId, TokenizerSettings};
use serde_json::Value as Json;
use sha2::{Digest, Sha256};
use std::borrow::Cow;
use std::sync::{atomic::AtomicBool, Arc};

macro_rules! oracle_set {
    ($set:literal) => {
        load($set,
            include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../tests/fixtures/rust-core/tokenizer/", $set, ".cases.json")),
            include_bytes!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../tests/fixtures/rust-core/tokenizer/", $set, ".expected.json")))
    };
}

// The message the oracle's fetch boundary throws for every artifact, so a web tokenizer stops where it would load one.
const ARTIFACT_BOUNDARY: &str = "synthetic artifact boundary";
// `db.google.accessToken` in every oracle database that has one.
const ACCESS_TOKEN: &str = "synthetic-google-key";
const COUNT_TOKENS: &str = "https://generativelanguage.googleapis.com/";

fn budget() -> Budget {
    let limits = Limits { max_owned_bytes: 256 << 20, max_json_bytes: 16 << 20, max_text_units: 16 << 20, max_values: 1 << 20,
        max_depth: 64, max_work: 1 << 40 };
    Budget::new(limits, Arc::new(AtomicBool::new(false))).unwrap()
}

// Each case paired with its expected result, after the header checks every replay shares.
fn load(set: &str, cases: &[u8], expected: &[u8]) -> Vec<(Json, Json)> {
    let digest = Sha256::digest(cases).iter().map(|byte| format!("{byte:02x}")).collect::<String>();
    let expected: Json = serde_json::from_slice(expected).unwrap();
    assert_eq!(expected["fixtureSha256"].as_str(), Some(digest.as_str()), "{set}: the expected file is stale");
    let cases: Json = serde_json::from_slice(cases).unwrap();
    let cases = cases["cases"].as_array().unwrap();
    let results = expected["cases"].as_array().unwrap();
    assert!(!cases.is_empty(), "{set}: no cases");
    assert_eq!(cases.len(), results.len(), "{set}: case count");
    cases.iter().zip(results).map(|(case, result)| {
        assert_eq!(case["id"], result["id"], "{set}: case order");
        (case.clone(), result["result"].clone())
    }).collect()
}

fn check(set: &str, pairs: &[(Json, Json)], mut matches: impl FnMut(&Json, &Json) -> Result<(), String>) {
    let mismatches = pairs.iter().filter_map(|(case, expected)| matches(case, expected).err().map(|reason| format!("{}: {reason}", case["id"])))
        .collect::<Vec<_>>();
    println!("{set}: {} cases, {} mismatches", pairs.len(), mismatches.len());
    assert!(mismatches.is_empty(), "{set}: {} of {} cases differ:\n{}", mismatches.len(), pairs.len(), mismatches.join("\n"));
}

// The cases of a set whose tokenizer this build leaves out: none with `huggingface`, otherwise the Hugging Face
// families and Google Cloud.
fn left_out_cases(set: &str, left: usize, without_huggingface: usize) {
    let expected = if cfg!(feature = "huggingface") { 0 } else { without_huggingface };
    println!("{set}: {left} cases left out of this build");
    assert_eq!(left, expected, "{set}: cases left out of this build");
}
// A text for a decline, which no tokenizer reads before declining.
fn probe(budget: &Budget) -> Text { Text::from_str("probe", budget).unwrap() }

// A string the oracle wrote: plain JSON when well-formed, otherwise `{"u": [units]}`.
fn units(text: &Json) -> Vec<u16> {
    match text {
        Json::String(value) => value.encode_utf16().collect(),
        _ => text["u"].as_array().unwrap().iter().map(|unit| unit.as_u64().unwrap() as u16).collect(),
    }
}
fn text(value: &Json, budget: &Budget) -> Text { Text::from_units(&units(value), budget).unwrap() }
fn shown(units: &[u16]) -> String { String::from_utf16_lossy(units) }

fn tokenizer(name: &str) -> TokenizerId { serde_json::from_value(Json::String(name.to_owned())).unwrap() }

// The oracle's synthetic tokenizerFunc, by the reply rule a case names.
fn reply(rule: &str, text: &Text) -> HostReply {
    match rule {
        "code-points" => HostReply::Tokens(char::decode_utf16(text.units())
            .map(|unit| unit.map_or_else(|error| error.unpaired_surrogate() as f64, |character| character as u32 as f64)).collect()),
        "half-length" => HostReply::Tokens(vec![text.len_units() as f64 / 2.0]),
        "none" => HostReply::Value(Value::Undefined),
        "empty" => HostReply::Tokens(Vec::new()),
        rule => panic!("unknown reply rule {rule}"),
    }
}

// The countTokens answer a case's API gives one request.
type Answer<'a> = Box<dyn FnMut(&HttpRequestSpec) -> HostReply + 'a>;

// Answers each plugin tokenizer request by the case's reply rule and records its text, as the oracle does, and each
// HTTP request with the case's API, recording what was sent.
struct Host<'a> { rule: Option<&'a str>, requests: Vec<Vec<u16>>, http: Option<Answer<'a>>, sent: Vec<HttpRequestSpec> }
impl<'a> Host<'a> {
    fn new(rule: Option<&'a str>) -> Self { Self { rule, requests: Vec::new(), http: None, sent: Vec::new() } }
    fn with_http(mut self, answer: impl FnMut(&HttpRequestSpec) -> HostReply + 'a) -> Self {
        self.http = Some(Box::new(answer));
        self
    }
    fn drive<T>(&mut self, mut step: Result<Step<T>, StageError>, mut resume: impl FnMut(HostReply) -> Result<Step<T>, StageError>)
        -> Result<T, StageError> {
        loop {
            match step? {
                Step::Done(value) => return Ok(value),
                Step::NeedsHost(HostRequest::PluginTokenizer { text }) => {
                    self.requests.push(text.units().collect());
                    let rule = self.rule.expect("a plugin tokenizer request in a case without a reply rule");
                    step = resume(reply(rule, &text));
                }
                Step::NeedsHost(HostRequest::Http(spec)) => {
                    let answer = self.http.as_mut().expect("an HTTP request in a case without an API");
                    let reply = answer(&spec);
                    self.sent.push(spec);
                    step = resume(reply);
                }
                Step::NeedsHost(request) => panic!("unexpected host request {request:?}"),
            }
        }
    }
    // The requests in TS order, repeats included.
    fn matches(&self, expected: &Json) -> Result<(), String> {
        let expected = expected.as_array().unwrap().iter().map(units).collect::<Vec<_>>();
        if expected == self.requests { return Ok(()); }
        let list = |requests: &[Vec<u16>]| requests.iter().map(|request| shown(request)).collect::<Vec<_>>();
        Err(format!("requests {:?}, TS made {:?}", list(&self.requests), list(&expected)))
    }
}

// The stage error that stands for the error TS throws.
fn stage_error(message: &str) -> StageError {
    let invalid = |name: &'static str| StageError::Invalid(Cow::Borrowed(name));
    if message.starts_with("The text contains a special token that is not allowed: ") { invalid("tokenizer-special-token") }
    else if message == "Local tokenization requires a Hugging Face model (hf:::)." { invalid("local-tokenizer-model") }
    else if message.ends_with(" is not valid JSON") { invalid("json-syntax") }
    else if message == "Unexpected end of JSON input" { invalid("json-syntax") }
    else if message == "Cannot read properties of undefined (reading 'toLocaleUpperCase')" { invalid("strong-ban-text") }
    else if message == "Cannot read properties of null (reading 'totalTokens')" { invalid("google-cloud-response") }
    else if message.starts_with("Invalid typed array length: ") { invalid("google-cloud-token-length") }
    else { panic!("no stage error stands for {message:?}") }
}

fn outcome<T>(actual: Result<T, StageError>, expected: &Json, same: impl FnOnce(T, &Json) -> Result<(), String>) -> Result<(), String> {
    match (actual, expected.get("error").and_then(Json::as_str)) {
        (Ok(value), None) => same(value, expected),
        (Err(error), Some(message)) if error == stage_error(message) => Ok(()),
        (Err(error), Some(message)) => Err(format!("{error:?} where TS threw {message:?}")),
        (Ok(_), Some(message)) => Err(format!("succeeded where TS threw {message:?}")),
        (Err(error), None) => Err(format!("{error:?} where TS returned {expected}")),
    }
}

fn same_ids(actual: &[f64], expected: &Json) -> Result<(), String> {
    let expected = expected.as_array().unwrap().iter().map(|id| id.as_f64().unwrap()).collect::<Vec<_>>();
    if actual == expected.as_slice() { Ok(()) } else { Err(format!("ids {actual:?}, TS returned {expected:?}")) }
}
fn same_count(actual: u32, expected: &Json) -> Result<(), String> {
    if expected.as_f64() == Some(actual as f64) { Ok(()) } else { Err(format!("count {actual}, TS returned {expected}")) }
}

fn no_fetches(fetches: &[Json]) -> Result<(), String> {
    if fetches.is_empty() { Ok(()) } else { Err(format!("TS fetched {fetches:?}")) }
}
fn url(fetch: &Json) -> &str { fetch["url"].as_str().unwrap_or_default() }
// What TS fetches for a tokenizer this crate runs: nothing, or its pinned model, whenever the
// tokenizer TS keeps loaded is another one, with the fingerprint the table records.
fn model_loads(id: TokenizerId, fetches: &[Json]) -> Result<(), String> {
    let model = id.artifact().filter(|artifact| matches!(artifact.format, ArtifactFormat::SentencePiece | ArtifactFormat::HuggingFace));
    let loads = |fetch: &Json| model.is_some_and(|model| url(fetch) == model.path && fetch["sha256"].as_str() == Some(model.sha256));
    if fetches.iter().all(loads) { Ok(()) } else { Err(format!("{id:?}: TS fetched {fetches:?}")) }
}

// What TS does with a tokenizer this crate declines: a web tokenizer fetches its artifact, which the oracle withholds.
fn declined_observation(id: TokenizerId, expected: &Json) -> Result<(), String> {
    let fetches = expected["fetches"].as_array().unwrap();
    let path = id.artifact().map(|artifact| artifact.path);
    if expected["error"].as_str() == Some(ARTIFACT_BOUNDARY) && fetches.len() == 1 && Some(url(&fetches[0])) == path { Ok(()) }
    else { Err(format!("{id:?} would load {path:?}; TS observed {expected}")) }
}

// The countTokens request TS sent, field by field, since the spec's `Debug` hides the query and the body. `fetch` reads
// the URL as a USVString, so an isolated surrogate there is sent as U+FFFD.
fn same_request(spec: &HttpRequestSpec, fetched: &Json) -> Result<(), String> {
    let url = String::from_utf16_lossy(&units(&fetched["url"]));
    let headers = fetched["headers"].as_array().map(|headers| headers.iter()
        .map(|pair| (pair[0].as_str().unwrap_or_default().to_owned(), pair[1].as_str().unwrap_or_default().to_owned())).collect::<Vec<_>>());
    let body = fetched["body"].as_str().unwrap_or_default();
    if spec.method != HttpMethod::Post || fetched["method"] != "POST" { return Err(format!("{:?} where TS sent {}", spec.method, fetched["method"])); }
    if spec.url != url { return Err(format!("url {} where TS fetched {url}", spec.url)); }
    if Some(&spec.headers) != headers.as_ref() { return Err(format!("headers {:?} where TS sent {headers:?}", spec.headers)); }
    if spec.body != body.as_bytes() { return Err(format!("body {} where TS sent {body}", String::from_utf8_lossy(&spec.body))); }
    if spec.response != ResponseKind::Buffered { return Err(format!("response {:?}", spec.response)); }
    Ok(())
}
fn google_cloud(internal_id: &Json, token: Option<&str>, memo: &GoogleCloudMemo, budget: &Budget) -> GoogleCloud {
    GoogleCloud { internal_id: text(internal_id, budget), access_token: token.map(|token| Text::from_str(token, budget).unwrap()), memo: memo.clone() }
}
// The oracle's fetch mock, for a URL it has no answer for.
fn unexpected(spec: &HttpRequestSpec, budget: &Budget) -> HostReply {
    HostReply::Failed { message: Text::from_str(&format!("Unexpected fetch {}", spec.url), budget).unwrap() }
}

// A selection case's API: the status it names, with `{}` or `{totalTokens}` as the oracle's mock serializes them.
fn selection_api<'a>(google: Option<&'a Json>, budget: &'a Budget) -> impl FnMut(&HttpRequestSpec) -> HostReply + 'a {
    move |spec| match google {
        Some(google) => {
            let body = google.get("totalTokens").map_or_else(|| "{}".to_owned(), |total| format!("{{\"totalTokens\":{total}}}"));
            HostReply::Http { status: google["status"].as_u64().unwrap() as u16, body: body.into_bytes() }
        }
        None => unexpected(spec, budget),
    }
}

// Google Cloud selection keeps exact HTTP requests and real API or Gemma IDs/counts.
fn google_observation(sent: [&[HttpRequestSpec]; 2], encoded: Result<Vec<f64>, StageError>, counted: Result<u32, StageError>,
    expected: &Json) -> Result<(), String> {
    let fetches = expected["fetches"].as_array().unwrap();
    let first = fetches.first().ok_or("TS sent no countTokens request")?;
    for sent in sent {
        if sent.len() != 1 { return Err(format!("{} requests where TS sent one", sent.len())); }
        same_request(&sent[0], first)?;
    }
    model_loads(TokenizerId::Gemma, &fetches[1..])?;
    let ids = encoded.map_err(|error| format!("{error:?}"))?;
    same_ids(&ids, &expected["ids"])?;
    same_count(counted.map_err(|error| format!("{error:?}"))?, &Json::from(ids.len()))
}

#[test]
fn oracle_selection() {
    let mut left = 0;
    check("selection", &oracle_set!("selection"), |case, expected| {
        let budget = budget();
        let settings = &case["settings"];
        let ai_model = text(&settings["aiModel"], &budget);
        let custom = settings["customTokenizer"].as_str().map(|name| Text::from_str(name, &budget).unwrap());
        let plugin = settings.get("plugin");
        let plugin_tokenizer = plugin.and_then(|plugin| plugin["tokenizer"].as_str()).map(|name| Text::from_str(name, &budget).unwrap());
        let rule = plugin.and_then(|plugin| plugin["reply"].as_str());
        // getModelInfo runs in TS: the model catalog stays outside this crate, so the case takes the tokenizer it found.
        let model_tokenizer = expected["modelTokenizer"].as_f64().map_or(ModelTokenizer::Other, ModelTokenizer::from_number);
        let settings = TokenizerSettings {
            ai_model: &ai_model,
            custom_tokenizer: custom.as_ref(),
            google_claude_tokenizing: settings["googleClaudeTokenizing"].as_bool().unwrap_or(false),
            model_tokenizer,
            plugin: plugin.map(|_| PluginOptions { tokenizer: plugin_tokenizer.as_ref(), tokenizer_function: rule.is_some() }),
        };
        let probe = text(&case["text"], &budget);
        let fetches = expected["fetches"].as_array().unwrap();
        let id = match select(&settings) {
            Ok(id) => id,
            Err(error) => return outcome(Err::<(), _>(error), expected, |(), _| Ok(())).and_then(|()| no_fetches(fetches)),
        };
        if left_out(id).is_some() {
            left += 1;
            return declines(id, &probe, &budget);
        }
        let id = ready(id);
        // The encoder and the counter each start from an empty memo, so both send the request TS sent once.
        let (encoder_memo, counter_memo) = (GoogleCloudMemo::new(), GoogleCloudMemo::new());
        let google = |memo: &GoogleCloudMemo| (id == TokenizerId::GoogleCloud)
            .then(|| google_cloud(&expected["internalID"], Some(ACCESS_TOKEN), memo, &budget));
        let mut host = Host::new(rule).with_http(selection_api(case.get("google"), &budget));
        let mut encoder = Encoder::new(id);
        if let Some(google) = google(&encoder_memo) { encoder = encoder.with_google_cloud(google); }
        let encoded = host.drive(encoder.encode(&probe, &budget), |reply| encoder.resume(reply, &budget));
        let mut counter = Counter::new(id, ChatAccounting::default());
        if let Some(google) = google(&counter_memo) { counter = counter.with_google_cloud(google); }
        let mut counter_host = Host::new(rule).with_http(selection_api(case.get("google"), &budget));
        let counted = counter_host.drive(counter.count(TokenInput::Text(&probe), &budget), |reply| counter.resume(reply, &budget));
        host.matches(&expected["requests"])?;
        if id == TokenizerId::GoogleCloud {
            return google_observation([&host.sent, &counter_host.sent], encoded, counted, expected);
        }
        if !host.sent.is_empty() || !counter_host.sent.is_empty() { return Err(format!("{id:?} sent HTTP requests")); }
        if let Some(decline) = id.decline() {
            let declined = StageError::Unsupported(Cow::Borrowed(decline));
            if encoded.as_ref().err() != Some(&declined) || counted.as_ref().err() != Some(&declined) {
                return Err(format!("{id:?}: expected the decline {decline}, got {encoded:?} and {counted:?}"));
            }
            return declined_observation(id, expected);
        }
        model_loads(id, fetches)?;
        let ids = encoded.map_err(|error| format!("{id:?}: {error:?}"))?;
        same_ids(&ids, &expected["ids"])?;
        match counted {
            Ok(count) if count as usize == ids.len() => Ok(()),
            counted => Err(format!("count {counted:?} for {} ids", ids.len())),
        }
    });
    left_out_cases("selection", left, SELECTION_WITHOUT_HUGGINGFACE);
}

// The selection cases that pick a Hugging Face family or Google Cloud.
const SELECTION_WITHOUT_HUGGINGFACE: usize = 49;

// risuChatParser as the oracle recorded it for one tokenizeAccurate text: it answers the recorded input only.
struct ParserTape { input: Vec<u16>, output: Vec<u16> }
impl TextProcessor for ParserTape {
    fn process(&mut self, input: &Text, context: &TextContext, budget: &Budget) -> Result<TextOutput, StageError> {
        let options = context.chat_index == -1 && context.role.is_none() && !context.run_var && !context.rm_var && !context.visualize;
        if !options || input.units().collect::<Vec<_>>() != self.input { return Err(StageError::Invalid(Cow::Borrowed("parser-tape"))); }
        Ok(TextOutput { text: Text::from_units(&self.output, budget)?, effects: Vec::new() })
    }
    fn apply(&mut self, _: &Effect, _: &Budget) -> Result<(), StageError> { Ok(()) }
}

fn message(value: &Json, budget: &Budget) -> PromptMessage {
    PromptMessage::from_value(json::parse(&value.to_string(), budget).unwrap(), budget).unwrap()
}

#[test]
fn oracle_accounting() {
    let mut left = 0;
    check("accounting", &oracle_set!("accounting"), |case, expected| {
        let budget = budget();
        let id = tokenizer(case["tokenizer"].as_str().unwrap());
        if left_out(id).is_some() {
            left += 1;
            return declines(id, &probe(&budget), &budget);
        }
        let id = ready(id);
        let caching = case["caching"].as_bool().unwrap_or(false);
        let accounting = ChatAccounting {
            additional_tokens: case["additional"].as_u64().unwrap_or(0) as u32,
            use_name: case["useName"].as_str() != Some("noName"),
            inlay_images: case["inlay"].as_bool().unwrap_or(false),
            low_vision_quality: case["visionQuality"].as_str().unwrap_or("low") == "low",
        };
        let new_counter = || if caching { Counter::new(id, accounting).with_plugin_memo() } else { Counter::new(id, accounting) };
        let mut host = Host::new(case["reply"].as_str());
        let count = |host: &mut Host<'_>, input: TokenInput<'_>| {
            let mut counter = new_counter();
            host.drive(counter.count(input, &budget), |reply| counter.resume(reply, &budget))
        };
        let totals = |host: &mut Host<'_>, texts: Result<Vec<(Text, usize)>, StageError>, buckets: usize| {
            let mut totals = TextTotals::new(new_counter());
            host.drive(texts.and_then(|texts| totals.start(texts, buckets, &budget)), |reply| totals.resume(reply, &budget))
        };
        let result = match case["call"].as_str().unwrap() {
            "tokenize" => outcome(count(&mut host, TokenInput::Text(&text(&case["text"], &budget))), expected,
                |count, expected| same_count(count, &expected["value"])),
            "tokenizeNum" => {
                let mut encoder = if caching { Encoder::new(id).with_plugin_memo() } else { Encoder::new(id) };
                let input = text(&case["text"], &budget);
                outcome(host.drive(encoder.encode(&input, &budget), |reply| encoder.resume(reply, &budget)), expected,
                    |ids, expected| same_ids(&ids, &expected["value"]))
            }
            "tokenizeChat" => outcome(count(&mut host, TokenInput::Message(&message(&case["message"], &budget))), expected,
                |count, expected| same_count(count, &expected["value"])),
            "tokenizeChats" => {
                let messages = case["messages"].as_array().unwrap().iter().map(|value| message(value, &budget)).collect::<Vec<_>>();
                outcome(count(&mut host, TokenInput::Messages(&messages)), expected, |count, expected| same_count(count, &expected["value"]))
            }
            "getChatToken" => {
                let messages = case["chat"].as_array().unwrap().iter().map(|data| text(data, &budget)).collect::<Vec<_>>();
                outcome(totals(&mut host, chat_texts(&messages, &budget), 1), expected, |counts, expected| same_count(counts[0], &expected["value"]))
            }
            "getCharToken" => {
                let character = &case["character"];
                let optional = |key: &str| character.get(key).map(|value| text(value, &budget));
                let (name, desc, personality, scenario) = (text(&character["name"], &budget), text(&character["desc"], &budget),
                    optional("personality"), optional("scenario"));
                let lore = character["globalLore"].as_array().unwrap().iter().map(|lore| text(&lore["content"], &budget)).collect::<Vec<_>>();
                let fields = CharacterFields { name: &name, desc: &desc, personality: personality.as_ref(), scenario: scenario.as_ref(), lore: &lore };
                outcome(totals(&mut host, character_texts(&fields, &budget), 2), expected, |counts, expected| {
                    same_count(counts[PERSISTANT], &expected["value"]["persistant"])?;
                    same_count(counts[DYNAMIC], &expected["value"]["dynamic"])
                })
            }
            "tokenizeAccurate" => {
                let parsed = &expected["parsed"];
                let mut parser = ParserTape { input: units(&parsed["input"]), output: units(&parsed["output"]) };
                let input = accurate_text(&text(&case["text"], &budget), &mut parser, &budget);
                match input {
                    Ok(input) => outcome(count(&mut host, TokenInput::Text(&input)), expected, |count, expected| same_count(count, &expected["value"])),
                    Err(error) => Err(format!("{error:?} before counting")),
                }
            }
            call => panic!("unknown call {call}"),
        };
        result?;
        host.matches(&expected["requests"])
    });
    // Three cases for each of the eight families.
    left_out_cases("accounting", left, 3 * 8);
}

#[test]
fn oracle_strong_ban() {
    let mut left = 0;
    check("strong-ban", &oracle_set!("strong-ban"), |case, expected| {
        let budget = budget();
        let id = tokenizer(case["tokenizer"].as_str().unwrap());
        if left_out(id).is_some() {
            left += 1;
            return declines(id, &probe(&budget), &budget);
        }
        let id = ready(id);
        let encoder = if case["caching"].as_bool().unwrap_or(false) { Encoder::new(id).with_plugin_memo() } else { Encoder::new(id) };
        let data = text(&case["data"], &budget);
        let mut key = "strongBan_".encode_utf16().collect::<Vec<_>>();
        key.extend(data.units());
        if cache_key(&data, &budget).unwrap().units().collect::<Vec<_>>() != key { return Err("the cache key differs from TS".into()); }
        let cached = case.get("cache").map(|cache| text(cache, &budget));
        let bias = json::parse(case["bias"].as_str().unwrap(), &budget).unwrap();
        let mut ban = StrongBan::new(encoder);
        let mut host = Host::new(case["reply"].as_str());
        // The recording's Node 24.12 maps case with Unicode 16 tables.
        let result = host.drive(ban.start(&data, bias, cached.as_ref(), false, CaseTables::Unicode16, &budget), |reply| ban.resume(reply, &budget));
        // localStorage after the call: what the owner writes back, or the entry it read.
        let stored = result.as_ref().ok().and_then(|result| result.store.as_ref()).or(cached.as_ref()).map(|stored| stored.units().collect::<Vec<_>>());
        let expected_stored = (!expected["stored"].is_null()).then(|| units(&expected["stored"]));
        if stored != expected_stored {
            return Err(format!("stored {:?}, TS stored {:?}", stored.as_deref().map(shown), expected_stored.as_deref().map(shown)));
        }
        outcome(result, expected, |result, expected| {
            let bias = json::stringify(&result.bias, &budget).unwrap().unwrap().units().collect::<Vec<_>>();
            if bias == units(&expected["result"]) { Ok(()) } else { Err(format!("bias {}, TS returned {}", shown(&bias), expected["result"])) }
        })?;
        host.matches(&expected["requests"])
    });
    left_out_cases("strong-ban", left, 3 * 8);
}

// An encode case's input, repeated when the case says so.
fn encode_input(case: &Json, budget: &Budget) -> Text {
    let input = &case["input"];
    let input = match input.get("repeat") {
        Some(repeat) => units(repeat).repeat(input["count"].as_u64().unwrap() as usize),
        None => units(input),
    };
    Text::from_units(&input, budget).unwrap()
}
fn encode_now(id: TokenizerId, input: &Text, budget: &Budget) -> Result<Vec<f64>, StageError> {
    Encoder::new(id).encode(input, budget).map(|step| match step {
        Step::Done(ids) => ids,
        Step::NeedsHost(request) => panic!("unexpected host request {request:?}"),
    })
}

#[test]
fn oracle_encode() {
    let mut left = 0;
    check("encode", &oracle_set!("encode"), |case, expected| {
        let budget = budget();
        let id = encode_with_tokenizer(&text(&case["tokenizer"], &budget));
        let input = encode_input(case, &budget);
        if left_out(id).is_some() {
            left += 1;
            return declines(id, &input, &budget);
        }
        let encoded = encode_now(ready(id), &input, &budget);
        model_loads(id, expected["fetches"].as_array().unwrap())?;
        outcome(encoded, expected, |ids, expected| same_ids(&ids, &expected["ids"]))
    });
    // claude and gemma 4 cases each, the six other families 3 each.
    left_out_cases("encode", left, 2 * 4 + 6 * 3);
}

// A google-cloud case's API: each request takes the next answer, a status with its body or the message `fetch` throws.
fn google_answer(answer: Option<&Json>, spec: &HttpRequestSpec, budget: &Budget) -> HostReply {
    let Some(answer) = answer else { return unexpected(spec, budget) };
    if let Some(message) = answer.get("throws") { return HostReply::Failed { message: text(message, budget) }; }
    let body = match answer.get("bytes") {
        Some(bytes) => bytes.as_array().unwrap().iter().map(|byte| byte.as_u64().unwrap() as u8).collect(),
        None => answer["body"].as_str().unwrap().as_bytes().to_vec(),
    };
    HostReply::Http { status: answer["status"].as_u64().unwrap() as u16, body }
}

enum Counted { Ids(Vec<f64>), Count(u32) }

// tokenizeGoogleCloud step by step, every step of a case sharing one memo as TS shares its module's: each step's
// countTokens requests, then its API or Gemma IDs/count, the error TS throws, or the
// decline the case names. A thrown `fetch` is `StageError::Host` with its message.
#[test]
fn oracle_google_cloud() {
    let mut left = 0;
    check("google-cloud", &oracle_set!("google-cloud"), |case, expected| {
        let budget = budget();
        if left_out(TokenizerId::GoogleCloud).is_some() {
            left += 1;
            return case["steps"].as_array().unwrap().iter()
                .try_for_each(|step| declines(TokenizerId::GoogleCloud, &text(&step["text"], &budget), &budget));
        }
        ready(TokenizerId::GoogleCloud);
        let memo = GoogleCloudMemo::new();
        let responses = case["responses"].as_array().unwrap();
        let mut answers = responses.iter();
        let thrown = |message: &str| responses.iter().any(|answer| answer["throws"].as_str() == Some(message));
        let steps = case["steps"].as_array().unwrap().iter().zip(expected["steps"].as_array().unwrap());
        for (index, (step, result)) in steps.enumerate() {
            let settings = google_cloud(&case["models"][step["model"].as_u64().unwrap() as usize], case["token"].as_str(), &memo, &budget);
            let input = text(&step["text"], &budget);
            let mut host = Host::new(None).with_http(|spec| google_answer(answers.next(), spec, &budget));
            let outcome = match step["call"].as_str().unwrap() {
                "encode" => {
                    let mut encoder = Encoder::new(TokenizerId::GoogleCloud).with_google_cloud(settings);
                    host.drive(encoder.encode(&input, &budget), |reply| encoder.resume(reply, &budget)).map(Counted::Ids)
                }
                "chat" => {
                    let message = message(&serde_json::json!({ "role": "user", "content": step["text"], "name": step["name"] }), &budget);
                    let accounting = ChatAccounting { additional_tokens: step["additional"].as_u64().unwrap_or(0) as u32, use_name: true, ..ChatAccounting::default() };
                    let mut counter = Counter::new(TokenizerId::GoogleCloud, accounting).with_google_cloud(settings);
                    host.drive(counter.count(TokenInput::Message(&message), &budget), |reply| counter.resume(reply, &budget)).map(Counted::Count)
                }
                call => panic!("unknown call {call}"),
            };
            let sent = std::mem::take(&mut host.sent);
            drop(host);
            let fetches = result["fetches"].as_array().unwrap();
            let requests = fetches.iter().filter(|fetch| url(fetch).starts_with(COUNT_TOKENS)).collect::<Vec<_>>();
            if sent.len() != requests.len() { return Err(format!("step {index}: {} requests where TS sent {}", sent.len(), requests.len())); }
            for (spec, fetched) in sent.iter().zip(requests) { same_request(spec, fetched).map_err(|reason| format!("step {index}: {reason}"))?; }
            let artifacts = fetches.iter().filter(|fetch| !url(fetch).starts_with(COUNT_TOKENS)).cloned().collect::<Vec<_>>();
            model_loads(TokenizerId::Gemma, &artifacts).map_err(|reason| format!("step {index}: {reason}"))?;
            let observed = match (outcome, result["error"].as_str()) {
                (Err(StageError::Unsupported(name)), None) if step["decline"].as_str() == Some(&*name) => Ok(()),
                (Err(StageError::Host(units)), Some(message)) if thrown(message) && units == message.encode_utf16().collect::<Vec<_>>() => Ok(()),
                (Err(error), Some(message)) if !thrown(message) && message != ARTIFACT_BOUNDARY && error == stage_error(message) => Ok(()),
                (Ok(Counted::Ids(ids)), None) if step["decline"].is_null() => same_ids(&ids, &result["value"]),
                (Ok(Counted::Count(count)), None) if step["decline"].is_null() => same_count(count, &result["value"]),
                (Ok(_), _) => Err(format!("succeeded where TS observed {result}")),
                (Err(error), _) => Err(format!("{error:?} where TS observed {result}")),
            };
            observed.map_err(|reason| format!("step {index}: {reason}"))?;
        }
        let unanswered = answers.count();
        if expected["unanswered"].as_u64() == Some(unanswered as u64) { Ok(()) }
        else { Err(format!("{unanswered} answers left where TS left {}", expected["unanswered"])) }
    });
    // Every case counts with Google Cloud.
    left_out_cases("google-cloud", left, 55);
}

// The decline of a case whose text a Hugging Face family other than Gemma screens out before encoding: a code point
// assigned after Unicode 14.0 (the `unicode-<version>-<class>` cases) in a class its pattern splits by, which for every
// family but DeepSeek's means letters and numbers, or a run past the regex engine's limits.
fn screened(case: &Json, id: TokenizerId) -> Option<&'static str> {
    let id_name = case["id"].as_str().unwrap();
    let name = id_name.split_once(':').map_or(id_name, |(_, name)| name);
    if id == TokenizerId::Gemma || id.artifact().is_none_or(|artifact| artifact.format != ArtifactFormat::HuggingFace) { return None; }
    if let Some((version, class)) = name.strip_prefix("unicode-").and_then(|rest| rest.split_once('-')) {
        let split = matches!(id, TokenizerId::DeepSeek | TokenizerId::DeepSeekV4) || class.starts_with("letter") || class == "number";
        return (version != "14.0" && split).then_some("tokenizer-unicode-version");
    }
    name.ends_with("-run-over-limit").then_some("tokenizer-regex-limit")
}

// Every web tokenizer over its real artifact: each admitted case's exact IDs and count, otherwise the decline and the
// artifact TS loaded, with the fingerprint the table records.
#[test]
fn oracle_web_encode() {
    let pairs = oracle_set!("web-encode");
    let mut compared = 0;
    let mut screened_out = 0;
    let mut left = 0;
    check("web-encode", &pairs, |case, expected| {
        let budget = budget();
        let id = encode_with_tokenizer(&text(&case["tokenizer"], &budget));
        let input = encode_input(case, &budget);
        let fetches = expected["fetches"].as_array().unwrap();
        if left_out(id).is_some() {
            // TS loaded the artifact the table names, which a build with the family would register.
            let artifact = id.artifact().unwrap();
            if !fetches.iter().all(|fetch| url(fetch) == artifact.path && fetch["sha256"].as_str() == Some(artifact.sha256)) {
                return Err(format!("{id:?}: TS observed {fetches:?}"));
            }
            left += 1;
            return declines(id, &input, &budget);
        }
        let id = ready(id);
        model_loads(id, fetches)?;
        if let Some(decline) = screened(case, id) {
            screened_out += 1;
            return declines_as(id, &input, &budget, decline);
        }
        compared += 1;
        outcome(encode_now(id, &input, &budget), expected, |ids, expected| same_ids(&ids, &expected["ids"]))?;
        let mut counter = Counter::new(id, ChatAccounting::default());
        match counter.count(TokenInput::Text(&input), &budget) {
            Ok(Step::Done(count)) => same_count(count, &Json::from(expected["ids"].as_array().unwrap().len())),
            counted => Err(format!("counted {counted:?}")),
        }
    });
    // Every web family compares exact IDs/counts, with the previous and Gemma/Cohere-specific boundaries; a build without
    // `huggingface` compares the four SentencePiece families. Of the 16 Unicode version cases of each Hugging Face family,
    // the two DeepSeek families decline the 12 past Unicode 14.0 and the five other families but Gemma the 7 letter and
    // number ones; DeepSeek declines both runs over its limit, and four patterns encode a class run at theirs.
    let all = 12 * 68 + 10 + 12 + 2 * (1283 + 14) + 5 + 3 * (291 + 18) + 7 + 61 + 2 * 14 + 7 + 6 + 8 * 16 + 4 + 4;
    let sentencepiece = 4 * 68 + 10;
    let declined = 2 * 12 + 5 * 7 + 2;
    assert_eq!((compared, screened_out), if cfg!(feature = "huggingface") { (all - declined, declined) } else { (sentencepiece, 0) });
    left_out_cases("web-encode", left, all - sentencepiece);
}

// A contract set: Node hashed the artifacts as the repository stores them.
#[test]
fn oracle_artifacts() {
    check("artifacts", &oracle_set!("artifacts"), |case, expected| {
        let id = tokenizer(case["tokenizer"].as_str().unwrap());
        let artifact = id.artifact().ok_or("no artifact")?;
        let file = match artifact.path.strip_prefix('/') {
            Some(path) => format!("public/{path}"),
            None if artifact.path.starts_with('@') => format!("node_modules/{}", artifact.path),
            None => artifact.path.to_owned(),
        };
        let format = match id {
            TokenizerId::Cl100kBase | TokenizerId::O200kBase => ArtifactFormat::Tiktoken,
            _ if file.ends_with(".model") => ArtifactFormat::SentencePiece,
            _ => ArtifactFormat::HuggingFace,
        };
        if file != case["file"].as_str().unwrap() || format != artifact.format { return Err(format!("{id:?} loads {file} as {:?}", artifact.format)); }
        if expected["sha256"].as_str() != Some(artifact.sha256) || expected["bytes"].as_u64() != Some(artifact.bytes) {
            return Err(format!("recorded {} ({} bytes), Node hashed {expected}", artifact.sha256, artifact.bytes));
        }
        Ok(())
    });
}

const ARTIFACT_IDS: [TokenizerId; 18] = [
    TokenizerId::Cl100kBase, TokenizerId::O200kBase, TokenizerId::Plugin, TokenizerId::PluginMissing, TokenizerId::Mistral,
    TokenizerId::Llama, TokenizerId::NovelAi, TokenizerId::Claude, TokenizerId::NovelList, TokenizerId::Llama3, TokenizerId::Gemma,
    TokenizerId::Cohere, TokenizerId::DeepSeek, TokenizerId::DeepSeekV4, TokenizerId::Glm4, TokenizerId::Glm5, TokenizerId::GoogleCloud,
    TokenizerId::Local,
];

// The artifacts the repository carries still have the recorded fingerprints, and `Artifact::verify` takes only those
// bytes: a JSON artifact with either line ending, a SentencePiece model byte for byte. The cl100k encoder JSON ships in
// node_modules, which the core CI job does not install.
#[test]
fn repository_artifacts_match_the_recorded_fingerprints() {
    let root = concat!(env!("CARGO_MANIFEST_DIR"), "/../../..");
    let declined = Err(StageError::Unsupported(Cow::Borrowed("tokenizer-artifact")));
    let mut checked = 0;
    let mut models = 0;
    let mut multiline = 0;
    for id in ARTIFACT_IDS {
        let Some(artifact) = id.artifact() else { continue };
        let path = match artifact.path.strip_prefix('/') {
            Some(path) => format!("{root}/public/{path}"),
            None if artifact.path.starts_with("src/") => format!("{root}/{}", artifact.path),
            None => continue,
        };
        let bytes = std::fs::read(&path).unwrap();
        assert_eq!(artifact.verify(&bytes), Ok(()), "{id:?}: {path}");
        let mut lf = Vec::with_capacity(bytes.len());
        for (index, byte) in bytes.iter().enumerate() {
            if !(*byte == b'\r' && bytes.get(index + 1) == Some(&b'\n')) { lf.push(*byte); }
        }
        let mut crlf = Vec::with_capacity(lf.len() * 2);
        for byte in &lf {
            if *byte == b'\n' { crlf.push(b'\r'); }
            crlf.push(*byte);
        }
        if artifact.format == ArtifactFormat::SentencePiece {
            // Every model holds both CRLF pairs and lone LF bytes, so each conversion changes it.
            assert!(lf != bytes && crlf != bytes, "{id:?}");
            assert_eq!(artifact.verify(&lf), declined, "{id:?}");
            assert_eq!(artifact.verify(&crlf), declined, "{id:?}");
            models += 1;
        } else {
            assert_eq!(artifact.verify(&lf), Ok(()), "{id:?}");
            assert_eq!(artifact.verify(&crlf), Ok(()), "{id:?}");
            if lf != crlf { multiline += 1; }
        }
        let mut flipped = bytes.clone();
        flipped[bytes.len() / 2] ^= 1;
        assert_eq!(artifact.verify(&flipped), declined, "{id:?}");
        assert_eq!(artifact.verify(&bytes[..bytes.len() - 1]), declined, "{id:?}");
        let shorter = risunest_tokenizer::id::Artifact { bytes: artifact.bytes - 1, ..artifact };
        assert_eq!(shorter.verify(&bytes), declined, "{id:?}");
        checked += 1;
    }
    // The Llama 3, Cohere and DeepSeek JSON artifacts span lines; the others are one line.
    assert_eq!((checked, models, multiline), (13, 4, 3));
}

// What one repository SentencePiece model holds, read from its bytes outside this crate.
struct RecordedModel {
    id: TokenizerId,
    name: &'static str,
    model_type: ModelType,
    // Normal, unknown, control, user-defined and byte pieces.
    kinds: [usize; 5],
    byte_fallback: bool,
    // unk, bos, eos and pad IDs.
    special: [i32; 4],
    normalizer: &'static str,
    charsmap: usize,
    add_dummy_prefix: bool,
    remove_extra_whitespaces: bool,
}

// The repository models parse to the vocabulary TS encodes with: the pieces behind the IDs the web-encode oracle
// recorded spell each input as the parsed normalizer settings prepare it.
#[test]
fn sentencepiece_models_parse_to_the_vocabulary_ts_encodes_with() {
    let root = concat!(env!("CARGO_MANIFEST_DIR"), "/../../../public");
    let pairs = oracle_set!("web-encode");
    let llama = |id, name| RecordedModel { id, name, model_type: ModelType::Bpe, kinds: [31741, 1, 2, 0, 256], byte_fallback: true,
        special: [0, 1, 2, -1], normalizer: "identity", charsmap: 0, add_dummy_prefix: true, remove_extra_whitespaces: false };
    let models = [
        llama(TokenizerId::Mistral, "mistral"),
        llama(TokenizerId::Llama, "llama"),
        RecordedModel { id: TokenizerId::NovelAi, name: "novelai", model_type: ModelType::Bpe, kinds: [65204, 1, 3, 71, 256], byte_fallback: true,
            special: [1, 2, 3, 0], normalizer: "identity", charsmap: 0, add_dummy_prefix: false, remove_extra_whitespaces: false },
        RecordedModel { id: TokenizerId::NovelList, name: "novellist", model_type: ModelType::Unigram, kinds: [51997, 1, 5, 0, 0],
            byte_fallback: false, special: [1, 2, 50256, 0], normalizer: "nmt_nfkc", charsmap: 237_539, add_dummy_prefix: false,
            remove_extra_whitespaces: true },
    ];
    for recorded in models {
        let name = recorded.name;
        let bytes = std::fs::read(format!("{root}{}", recorded.id.artifact().unwrap().path)).unwrap();
        let model = sentencepiece::parse(&bytes).unwrap();
        let kinds = [PieceType::Normal, PieceType::Unknown, PieceType::Control, PieceType::UserDefined, PieceType::Byte]
            .map(|kind| model.pieces.iter().filter(|piece| piece.kind == kind).count());
        assert_eq!((kinds, model.pieces.len()), (recorded.kinds, recorded.kinds.iter().sum()), "{name}");
        let trainer = &model.trainer_spec;
        assert_eq!((trainer.model_type, trainer.byte_fallback, [trainer.unk_id, trainer.bos_id, trainer.eos_id, trainer.pad_id]),
            (recorded.model_type, recorded.byte_fallback, recorded.special), "{name}");
        let normalizer = &model.normalizer_spec;
        assert_eq!((normalizer.name.as_str(), normalizer.precompiled_charsmap.len(), normalizer.add_dummy_prefix,
            normalizer.remove_extra_whitespaces), (recorded.normalizer, recorded.charsmap, recorded.add_dummy_prefix,
            recorded.remove_extra_whitespaces), "{name}");
        let recorded_case = |case: &str| {
            let (entry, result) = pairs.iter().find(|(entry, _)| entry["id"] == format!("{name}:{case}").as_str()).unwrap();
            let spelled = result["ids"].as_array().unwrap().iter().map(|id| model.pieces[id.as_u64().unwrap() as usize].piece.as_str())
                .collect::<String>();
            (entry["input"].clone(), spelled)
        };
        let prefix = if normalizer.add_dummy_prefix { "\u{2581}" } else { "" };
        for case in ["ascii-word", "inner-space-runs"] {
            let (input, spelled) = recorded_case(case);
            let input = input.as_str().unwrap();
            let input = if normalizer.remove_extra_whitespaces { input.split(' ').filter(|word| !word.is_empty()).collect::<Vec<_>>().join(" ") }
                else { input.to_owned() };
            assert_eq!(spelled, format!("{prefix}{}", input.replace(' ', "\u{2581}")), "{name}:{case}");
        }
        // The emscripten UTF-8 conversion web-tokenizers runs reads a lone high surrogate at the end as U+10000.
        let (input, spelled) = recorded_case("lone-high-surrogate");
        assert_eq!(units(&input), [0xd800], "{name}");
        let unknown = &model.pieces[trainer.unk_id as usize];
        assert_eq!(unknown.kind, PieceType::Unknown, "{name}");
        let expected = if trainer.byte_fallback { format!("{prefix}<0xF0><0x90><0x80><0x80>") } else { unknown.piece.clone() };
        assert_eq!(spelled, expected, "{name}");
    }
}

// `encode` reaches `tokenizeTransformers` only for an `hf:::` model; no oracle case downloads one.
#[test]
fn local_models_select_the_transformers_tokenizer_this_crate_declines() {
    let budget = budget();
    let model = Text::from_str("hf:::synthetic/model", &budget).unwrap();
    let settings = TokenizerSettings { ai_model: &model, custom_tokenizer: None, google_claude_tokenizing: false,
        model_tokenizer: ModelTokenizer::Local, plugin: None };
    assert_eq!(select(&settings), Ok(TokenizerId::Local));
    let declined = StageError::Unsupported(Cow::Borrowed("tokenizer-local"));
    assert_eq!(Counter::new(TokenizerId::Local, ChatAccounting::default()).count(TokenInput::Text(&model), &budget).err(), Some(declined.clone()));
    assert_eq!(Encoder::new(TokenizerId::Local).encode(&model, &budget).err(), Some(declined));
}
